import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Délais, objets et logique","description":"","frontmatter":{"title":"Délais, objets et logique"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/flow.md","filePath":"fr/projects/blocks-for-ha/flow.md","lastUpdated":1792862028000}'),r={name:"fr/projects/blocks-for-ha/flow.md"};function n(i,e,l,c,d,u){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="delais-objets-et-logique" tabindex="-1">Délais, objets et logique <a class="header-anchor" href="#delais-objets-et-logique" aria-label="Permalink to &quot;Délais, objets et logique&quot;">​</a></h1><p>Les blocs génèrent des <strong>actions natives HA</strong> et des expressions Jinja. Aucun temporisateur JavaScript n’exécute les actions dans le navigateur. <a href="./blocks">Tous les blocs avec images</a>.</p><h2 id="delais-et-boucles" tabindex="-1">Délais et boucles <a class="header-anchor" href="#delais-et-boucles" aria-label="Permalink to &quot;Délais et boucles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonction</th><th>Exécution HA</th></tr></thead><tbody><tr><td>Pause</td><td><code>delay</code>, durée numérique en ms, secondes, minutes ou heures. Les ms ne garantissent pas un temps réel précis.</td></tr><tr><td>Attendre une condition</td><td><code>wait_template</code>, durée maximale et case continuer après expiration. Sans coche, l’expiration termine cette exécution.</td></tr><tr><td>Arrêter</td><td><code>stop</code>, raison et indicateur d’erreur. Arrête l’exécution complète, boucles englobantes comprises.</td></tr><tr><td>Répéter N fois</td><td><code>repeat.count</code>, entier positif. Indice <code>repeat.index</code>, à partir de 1.</td></tr><tr><td>Tant que</td><td>Condition vérifiée avant chaque tour. Peut n’exécuter aucun tour.</td></tr><tr><td>Jusqu’à</td><td>Condition vérifiée après chaque tour. Au moins un tour.</td></tr><tr><td>Pour chaque élément</td><td><code>repeat.for_each</code>, élément <code>repeat.item</code>, indice <code>repeat.index</code>. Entrée liste obligatoire.</td></tr></tbody></table><p>Ajouter une pause si une boucle risque de tourner continuellement. Une condition d’attente doit dépendre d’entités : l’heure seule ne réévalue pas constamment <code>wait_template</code>. Les temporisateurs et intervalles nommés ioBroker ne sont pas équivalents à ces actions ; un arrêt de boucle complète n’est pas un <code>break</code> ou <code>continue</code> ciblé.</p><h2 id="objets-et-listes" tabindex="-1">Objets et listes <a class="header-anchor" href="#objets-et-listes" aria-label="Permalink to &quot;Objets et listes&quot;">​</a></h2><p>Un nouvel objet est un dictionnaire local. L’engrenage ajoute jusqu’à 100 clés. On peut lire un attribut, vérifier sa présence et obtenir la liste des clés. Clé absente : <code>null</code> ; objet invalide : erreur de modèle HA.</p><p>Modifier/supprimer un attribut affecte un <strong>nouveau dictionnaire</strong> à la variable. Initialiser la variable comme objet auparavant. Ces opérations ne modifient ni une autre variable ni les attributs d’une entité HA. Les listes sont aussi des valeurs locales ; les changements produisent de nouvelles listes compatibles avec le bac à sable Jinja immuable.</p><h2 id="logique-et-choix" tabindex="-1">Logique et choix <a class="header-anchor" href="#logique-et-choix" aria-label="Permalink to &quot;Logique et choix&quot;">​</a></h2><p>Comparaison, ET/OU, NON, booléens, null et choix de valeur sont disponibles. Les groupes ET/OU/NON peuvent être étendus avec l’engrenage. Utilisés comme conditions, ils génèrent les groupes natifs HA ; utilisés comme valeurs, ils génèrent des expressions Jinja.</p><p><strong>Si / sinon si / sinon</strong> crée des branches d’actions. <strong>Selon la valeur</strong> compare des cas, exécute seulement le premier cas correspondant puis utilise la branche par défaut si nécessaire. Il génère <code>choose</code>, sans passage automatique aux cas suivants de JavaScript.</p><p><strong>Limiter une valeur entre deux bornes</strong> vérifie un intervalle numérique, avec bornes strictes ou inclusives. <strong>Valeur de secours</strong> distingue null/non défini et vide/faux/0. Le premier mode conserve 0, faux et texte vide ; le second remplace aussi listes et objets vides selon les règles Python/Jinja.</p><p>Le choix conditionnel de <strong>valeur</strong> ne contient pas d’actions. Une condition seule ne déclenche aucune automatisation.</p><p><a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">Scripts HA</a> · <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">Sources ioBroker</a> · <a href="https://github.com/RaspberryPiFoundation/blockly" target="_blank" rel="noreferrer">Blockly</a>.</p><p>Depuis <strong>0.1.39</strong> : unités de durée combinées, listes for_each littérales, options HA, attente de déclencheur, timer.finished, branches parallèles et groupes d’actions. <a href="./advanced">Guide HA avancé et Jinja</a>.</p>',15)])])}const m=t(r,[["render",n]]);export{b as __pageData,m as default};
